// 独立冻结真实A+B+C+D组合46f6878c5。
const D = {
  "docs/registry/coding-workflow-authority.json": "{\n  \"object_id\": \"coding-workflow\",\n  \"selectors\": [{ \"repo\": \"cecelia\", \"scope\": \"coding-workflow\" }],\n  \"refs\": [\n    { \"ref_id\": \"spec\", \"kind\": \"spec\", \"path\": \"packages/brain/scripts/coding-workflow/runner/README.md\", \"required\": true },\n    { \"ref_id\": \"rule\", \"kind\": \"rule\", \"path\": \"packages/brain/scripts/coding-workflow/prompts/repo-rules/cecelia.md\", \"required\": true },\n    { \"ref_id\": \"sample\", \"kind\": \"sample\", \"path\": \"packages/brain/scripts/coding-workflow/__tests__/fixtures/activity-fixture.mjs\", \"required\": true },\n    { \"ref_id\": \"implementation\", \"kind\": \"implementation\", \"path\": \"packages/brain/scripts/coding-workflow/activities/intent.mjs\", \"required\": true }\n  ]\n}\n",
  "packages/brain/scripts/coding-workflow/__tests__/authority-inheritance.test.mjs": "import { it, expect, beforeEach, afterEach } from 'vitest';\nimport fs from 'node:fs';\nimport os from 'node:os';\nimport path from 'node:path';\nimport { spawn } from 'node:child_process';\nimport { fileURLToPath } from 'node:url';\nimport { git, gitPlain, initCommittableRepo } from './helpers/git.mjs';\nimport { startTestBrain } from './helpers/brain-transport.mjs';\nimport { runActivityProcess } from './helpers/run-activity.mjs';\nimport { runnerEnv, runOnceProcess, readJsonLines } from '../runner/__tests__/helpers/sandbox.mjs';\nconst WF = fileURLToPath(new URL('../', import.meta.url));\nconst INDEX = 'docs/registry/coding-workflow-authority.json';\nlet root, seed, clone, origin, brain, rows, env, index;\nconst save = (file,text) => { fs.mkdirSync(path.dirname(file),{recursive:true}); fs.writeFileSync(file,text); };\nconst commit = () => { git(seed,'add','.'); git(seed,'commit','-qm','change'); return git(seed,'rev-parse','HEAD').trim(); };\nconst publish = () => { git(seed,'push','-q','origin','main'); git(clone,'fetch','-q','origin','main'); };\nasync function create(overrides={}) {\n  const file=path.join(root,'plan.json'); save(file,JSON.stringify({title:'继承',change_kind:'bugfix',map_scope_hint:['F1'],acceptance:['保留旧规则'],object_id:'coding-workflow',...overrides}));\n  const t=brain.spawnOptions();\n  return new Promise((resolve,reject)=>{\n    const c=spawn(process.execPath,[...t.args,path.join(WF,'new-task.mjs'),file],{env:{...process.env,...env},stdio:t.stdio});t.attach(c);c.stdin?.end();\n    let stdout='',stderr='';c.stdout.on('data',d=>{stdout+=d;});c.stderr.on('data',d=>{stderr+=d;});c.once('error',reject);c.once('close',code=>resolve({code,stdout,stderr,task:rows.at(-1)}));\n  });\n}\nasync function intent(task,sprint,extra={}) {\n  const p=task.payload;\n  return runActivityProcess(path.join(WF,'activities/intent.mjs'),{task_id:task.id,worktree:clone,sprint_dir:sprint,brain_url:brain.url,authority_required:p.authority_required,authority:p.authority,authority_index_sha:p.authority_index_sha,initial_base_sha:p.base_sha,trusted_repo:clone,...extra},env,brain.spawnOptions());\n}\nbeforeEach(async()=>{\n  root=fs.mkdtempSync(path.join(os.tmpdir(),'cw-inherit-'));seed=path.join(root,'seed');clone=path.join(root,'clone');origin=path.join(root,'origin.git');\n  fs.mkdirSync(seed);initCommittableRepo(seed,path.join(root,'hooks'),'main');gitPlain('init','--bare','-q',origin);git(seed,'remote','add','origin',origin);\n  index={object_id:'coding-workflow',selectors:[{repo:'cecelia',scope:'coding-workflow'}],refs:['spec','rule','sample','implementation'].map(kind=>({ref_id:kind,kind,path:`authority/${kind}.md`,required:true}))};\n  save(path.join(seed,INDEX),JSON.stringify(index));for(const r of index.refs)save(path.join(seed,r.path),r.kind==='rule'?'<!-- rule: cw-keep -->\\n保留旧规则\\n':`${r.kind} v1\\n`);\n  save(path.join(seed,'packages/brain/scripts/coding-workflow/contract.json'),fs.readFileSync(path.join(WF,'contract.json'),'utf8'));\n  save(path.join(seed,'.gitignore'),'.dev-mode*\\n.dev-lock*\\n');\n  commit();git(seed,'push','-qu','origin','main');gitPlain('clone','-q','-b','main',origin,clone);git(clone,'config','user.name','fixture');git(clone,'config','user.email','fixture@example.com');git(clone,'config','core.hooksPath',path.join(root,'hooks'));\n  const repos=JSON.parse(fs.readFileSync(path.join(WF,'repos.json'),'utf8'));const primary=repos.repos.find(r=>r.default);primary.origin=origin;primary.clone=clone;save(path.join(root,'repos.json'),JSON.stringify(repos));rows=[];\n  brain=await startTestBrain(req=>{\n    const response=(body,status=200)=>({status,body:JSON.stringify(body)});\n    if(req.method==='POST'&&req.url==='/api/brain/tasks') {const b=JSON.parse(req.body);const row={...b,status:'queued',claimed_by:null,created_at:new Date().toISOString(),id:`${String(rows.length+1).padStart(8,'0')}-0000-4000-8000-000000000001`,payload:{...b.payload,base_sha:b.base_sha,change_kind:b.change_kind,map_scope:b.map_scope_hint,work_kind:'coding_mutation',orchestrator:'coding-workflow-runner'}};rows.push(row);return response(row,201);}\n    if(req.method==='GET'&&req.url.startsWith('/api/brain/tasks?')) {const q=new URL(req.url,'http://x').searchParams; return response(rows.filter(r=>r.status===q.get('status')&&r.task_type===q.get('task_type')));}\n    if(req.method==='POST'&&req.url.endsWith('/claim')) { const row=rows.find(r=>req.url.includes(r.id));Object.assign(row,{claimed_by:'fixture',executor_kind:'coding-workflow-runner'});return response(row); }\n    if(req.method==='PATCH'&&req.url.startsWith('/api/brain/tasks/')) {const row=rows.find(r=>req.url.endsWith(r.id));const b=JSON.parse(req.body);Object.assign(row,{...b,...(b.result?{result:{...row.result,...b.result}}:{})});return response(row);}\n    if(req.method==='POST'&&req.url==='/api/brain/spans') return response({inserted:1},201);\n    if(req.method==='GET'&&req.url.startsWith('/api/brain/tasks/'))return response(rows.find(r=>req.url.endsWith(r.id)));\n    if(req.method==='GET'&&req.url.startsWith('/api/brain/decisions?'))return response([]);return response({},404);\n  });\n  env={BRAIN_URL:brain.url,CODING_WF_TRUSTED_REPO:clone,CODING_WF_REPOS_FILE:path.join(root,'repos.json')};\n});\nafterEach(async()=>{await brain?.close();fs.rmSync(root,{recursive:true,force:true});});\nit('真实入口自动选择：两候选不生效，合并后新任务继承，旧任务重试冻结',async()=>{\n  const a=await create();expect(a.code,a.stderr).toBe(0);const base=a.task.payload.base_sha;expect(base).toMatch(/^[a-f0-9]{40}$/);expect(a.task.payload.authority_index_sha).toBe(base);\n  const r=await intent(a.task,'sprints/first');expect(r.result?.status,r.stderr).toBe('completed');const original=fs.readFileSync(path.join(clone,'sprints/first/01-intent.md'),'utf8');\n  git(seed,'checkout','-qb','candidate-one');save(path.join(seed,'authority/sample.md'),'sample v2\\n');save(path.join(seed,'authority/spec.md'),'spec v2\\n');const candidate=commit();git(seed,'push','-q','origin','candidate-one');\n  git(seed,'checkout','-qb','candidate-two',base);save(path.join(seed,'authority/sample.md'),'sample rejected\\n');commit();git(seed,'push','-q','origin','candidate-two');\n  const pending=await create();expect(pending.code,pending.stderr).toBe(0);expect(pending.task.payload.base_sha).toBe(base);\n  git(seed,'checkout','-q','main');git(seed,'merge','--no-ff','-m','merge candidate one',candidate);publish();\n  const b=await create({object_id:undefined,authority_scope:'coding-workflow'});expect(b.code,b.stderr).toBe(0);expect(b.task.payload.base_sha).not.toBe(base);expect(b.task.payload.authority.refs.find(r=>r.kind==='sample').digest).not.toBe(a.task.payload.authority.refs.find(r=>r.kind==='sample').digest);\n  const r2=await intent(b.task,'sprints/second');expect(r2.result?.status,r2.stderr).toBe('completed');\n  const retry=await intent(a.task,'sprints/first');expect(retry.result?.status,retry.stderr).toBe('completed');expect(fs.readFileSync(path.join(clone,'sprints/first/01-intent.md'),'utf8')).toBe(original);expect(b.task.payload).not.toHaveProperty('deployed');\n});\nit('未知对象/范围拒绝；未声明旧任务未配置',async()=>{\n  expect((await create({object_id:'other'})).stderr).toContain('authority_object_unsupported');expect((await create({object_id:undefined,authority_scope:'other'})).stderr).toContain('authority_scope_unmatched');\n  const a=await create({object_id:undefined});expect(a.code,a.stderr).toBe(0);expect(a.task.payload.authority).toBeUndefined();const r=await intent(a.task,'sprints/legacy');expect(r.result?.status).toBe('completed');expect(fs.readFileSync(path.join(clone,'sprints/legacy/01-intent.md'),'utf8')).toContain('legacy/unconfigured');\n});\nit('多匹配及缺资料在建单前拒绝',async()=>{\n  index.selectors.push({...index.selectors[0]});save(path.join(seed,INDEX),JSON.stringify(index));commit();publish();expect((await create({object_id:undefined,authority_scope:'coding-workflow'})).stderr).toContain('authority_scope_ambiguous');expect(rows).toHaveLength(0);\n  index.selectors.pop();save(path.join(seed,INDEX),JSON.stringify(index));fs.rmSync(path.join(seed,'authority/sample.md'));commit();publish();expect((await create()).stderr).toContain('authority_file_missing');expect(rows).toHaveLength(0);\n});\nit('真实remote已前进而本地tracking未更新，拒绝陈旧引用；显式旧base不能覆盖新选择',async()=>{\n  const base=git(clone,'rev-parse','origin/main').trim();save(path.join(seed,'authority/spec.md'),'spec v2');commit();git(seed,'push','-q','origin','main');\n  expect((await create()).stderr).toContain('authority_index_stale');expect(rows).toHaveLength(0);git(clone,'fetch','-q','origin','main');\n  expect((await create({base_sha:base})).stderr).toContain('authority_selection_base_mismatch');expect(rows).toHaveLength(0);\n});\nit('索引路径变化不漂移旧任务；伪造新的index信封拒绝；中断后可以重放',async()=>{\n  const a=await create();expect(a.code,a.stderr).toBe(0);const frozen=a.task.payload.authority_index_sha;\n  index.refs.find(r=>r.kind==='sample').path='authority/sample-v2.md';save(path.join(seed,'authority/sample-v2.md'),'v2');save(path.join(seed,INDEX),JSON.stringify(index));commit();publish();\n  const bad=await intent(a.task,'sprints/interrupted',{authority_index_sha:git(clone,'rev-parse','origin/main').trim()});expect(bad.result?.reason_code).toBe('authority_index_binding_mismatch');expect(fs.existsSync(path.join(clone,'sprints/interrupted/01-intent.md'))).toBe(false);\n  const good=await intent(a.task,'sprints/interrupted');expect(good.result?.status,good.stderr).toBe('completed');expect(fs.readFileSync(path.join(clone,'sprints/interrupted/01-intent.md'),'utf8')).toContain(`revision: ${frozen}`);\n  const b=await create();expect(b.code,b.stderr).toBe(0);expect(b.task.payload.authority.refs.find(r=>r.kind==='sample').path).toBe('authority/sample-v2.md');\n});\nit('远端不可达与symlink资料均明确失败',async()=>{\n  fs.rmSync(path.join(seed,'authority/sample.md'));fs.symlinkSync('/etc/hosts',path.join(seed,'authority/sample.md'));commit();publish();expect((await create()).stderr).toContain('authority_non_regular_file');\n  git(clone,'remote','set-url','origin',path.join(root,'missing.git'));expect((await create()).stderr).toContain('authority_remote_unavailable');expect(rows).toHaveLength(0);\n});\nit('未知仓库仍正常返回计划错误，不因自动选择崩溃',async()=>{\n  const r=await create({repo:'unknown-repo'});expect(r.code).toBe(2);expect(r.stderr).toContain('repo_unknown');expect(r.stderr).not.toContain('TypeError');expect(rows).toHaveLength(0);\n});\nit.each([{}, [null]])('索引selectors非法形状%j返回明确业务错误',async(selectors)=>{\n  index.selectors=selectors;save(path.join(seed,INDEX),JSON.stringify(index));commit();publish();const r=await create({object_id:undefined,authority_scope:'coding-workflow'});expect(r.stderr).toContain('authority_selectors_invalid');expect(r.stderr).not.toContain('TypeError');expect(rows).toHaveLength(0);\n});\nit('对象与范围必须同时匹配，手写引用与scope不得静默混用',async()=>{\n  const a=await create();expect(a.code,a.stderr).toBe(0);\n  expect((await create({authority_scope:'other'})).stderr).toContain('authority_scope_unmatched');\n  expect((await create({object_id:undefined,authority:a.task.payload.authority,authority_scope:'coding-workflow'})).stderr).toContain('authority_selection_conflict');\n});\n\nasync function runPipeline(task, extra={}, expected='completed') {\n  const sb={root,clone,worktreeBase:path.join(root,'wt'),logDir:path.join(root,'logs'),lockDir:path.join(root,'locks'),execLog:path.join(root,'executor.log'),ghLog:path.join(root,'gh.log')};\n  const log=path.join(root,'intent-results.jsonl');\n  const runner=await runOnceProcess(runnerEnv(sb,brain.url,{...env,FAKE_EXEC_MODE:'real-intent',FAKE_INTENT_ENTRY:path.join(WF,'activities/intent.mjs'),FAKE_INTENT_LOG:log,FAKE_SPEC_ENTRY:path.join(WF,'activities/spec.mjs'),FAKE_BUILD_ENTRY:path.join(WF,'activities/build.mjs'),...extra}),brain);\n  expect(runner.exitCode,runner.stderr).toBe(expected==='completed'?0:1);\n  const result=readJsonLines(log).find(r=>r.task_id===task.id);\n  expect(result).toBeDefined();expect(result.result.status).toBe(expected);return result;\n}\nit('new-task到真实runner到真实intent连续两次交接，不由测试拼活动输入',async()=>{\n  const a=await create();expect(a.code,a.stderr).toBe(0);const first=await runPipeline(a.task);expect(first.intent).toContain('status: found');\n  git(seed,'checkout','-qb','product-candidate');save(path.join(seed,'authority/spec.md'),'spec v2');save(path.join(seed,'authority/sample.md'),'sample v2');const candidate=commit();git(seed,'checkout','-q','main');git(seed,'merge','--no-ff','-m','merge product candidate',candidate);publish();\n  const b=await create();expect(b.code,b.stderr).toBe(0);const second=await runPipeline(b.task);\n  expect(second.input.authority_index_sha).toBe(b.task.payload.authority_index_sha);expect(second.input.initial_base_sha).toBe(b.task.payload.base_sha);expect(second.intent).not.toBe(first.intent);\n  expect(first.input.authority.refs.find(r=>r.kind==='rule').digest).toBe(second.input.authority.refs.find(r=>r.kind==='rule').digest);\n});\n\nit('完整材料链：实际合并C1后B1入口继承长期规格样本，四阶段和回写版本可追溯',async()=>{\n  const entries={FAKE_MATERIAL_CHAIN:'1',FAKE_CHAIN_ENTRY:path.join(WF,'activities/chain-check.mjs'),FAKE_REPORT_ENTRY:path.join(WF,'activities/report.mjs')};\n  const a=await create({acceptance:['批准更新 sample；更新长期规格并保留旧规则']});expect(a.code,a.stderr).toBe(0);\n  const first=await runPipeline(a.task,{...entries,FAKE_MATERIAL_UPDATE:'1'});expect(first.materials.material_sync.status).toBe('verified');expect(first.materials.artifacts).toHaveLength(4);\n  expect(a.task.result.coding_workflow.versions).toMatchObject({baseline:a.task.payload.base_sha,candidate:first.materials.candidate,merged:'unknown',deployed:'unknown'});\n  git(clone,'push','-q','origin',`${first.materials.candidate}:refs/heads/material-candidate`);git(seed,'fetch','-q','origin','material-candidate');git(seed,'merge','--no-ff','-m','merge material C1','FETCH_HEAD');publish();\n  const b=await create();expect(b.code,b.stderr).toBe(0);const second=await runPipeline(b.task,entries);expect(second.materials.material_sync.status).toBe('verified');\n  expect(second.input.authority.refs.find(r=>r.kind==='sample').digest).not.toBe(first.input.authority.refs.find(r=>r.kind==='sample').digest);expect(second.input.authority.refs.find(r=>r.kind==='rule').digest).toBe(first.input.authority.refs.find(r=>r.kind==='rule').digest);\n  expect(b.task.result.coding_workflow.versions.deployed).toBe('unknown');\n});\n\nit.each([['omit_rule','rule_missing:rule#cw-keep'],['conflict','rule_conflict:rule#cw-keep'],['unauthorized_sample','approval_missing:sample']])('真实入口整链拒绝%s',async(variant,error)=>{\n  const a=await create();expect(a.code,a.stderr).toBe(0);\n  const r=await runPipeline(a.task,{FAKE_MATERIAL_CHAIN:'1',FAKE_CHAIN_ENTRY:path.join(WF,'activities/chain-check.mjs'),FAKE_REPORT_ENTRY:path.join(WF,'activities/report.mjs'),FAKE_MATERIAL_UPDATE:variant==='unauthorized_sample'?'1':'0',FAKE_MATERIAL_VARIANT:variant},'failed');\n  expect(JSON.stringify(r.materials.result)).toContain(error);expect(a.task.result?.coding_workflow?.material_sync).toBeUndefined();\n});\nit('自动选择没有明确仓库登记不得跨业务套用；完整旧引用仍兼容',async()=>{\n  const a=await create();expect(a.code,a.stderr).toBe(0);delete index.selectors;save(path.join(seed,INDEX),JSON.stringify(index));commit();publish();\n  expect((await create()).stderr).toContain('authority_object_unconfigured');\n  const explicit=await create({object_id:undefined,authority:a.task.payload.authority});expect(explicit.code,explicit.stderr).toBe(0);\n});\n",
  "packages/brain/scripts/coding-workflow/activities/intent.mjs": "// intent 活动：GET Brain 任务 → 提取验收条目 → 写 <sprint_dir>/01-intent.md；\n// 另拉全部 active 铁律写 01-invariants.md，供合同逐条对照（审计 P1 #3）。\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { runActivity, validateBase, fail, log } from '../lib/protocol.mjs';\nimport { extractAcceptance, renderIntent } from '../lib/intent.mjs';\nimport { sha256File } from '../lib/guards.mjs';\nimport { renderInvariants, INVARIANTS_FILE } from '../lib/invariants.mjs';\nimport { validateAuthority, resolveAuthority, sameAuthority, commitAvailable, loadAuthorityIndex, authorityFromPayload } from '../lib/authority-refs.mjs';\nimport { execFileSync } from 'node:child_process';\nimport { resolveRepo } from '../runner/lib/repos.mjs';\n\nconst INTENT_FILE = '01-intent.md';\nconst INVARIANT_LIMIT = 1000;\nconst DEFAULT_BRAIN_URL = 'http://localhost:5221';\nconst FETCH_TIMEOUT_MS = 30000;\n\nawait runActivity(async (input) => {\n  // 先校验输入，再做任何网络请求或写文件\n  const { dir } = validateBase(input);\n  const taskId = input.task_id;\n  // 重试失败时不能留下上一轮成功的 01，让后继误读。\n  fs.rmSync(path.join(dir, INTENT_FILE), { force: true });\n\n  const base = String(input.brain_url || DEFAULT_BRAIN_URL).replace(/\\/+$/, '');\n  const url = `${base}/api/brain/tasks/${encodeURIComponent(taskId)}`;\n\n  let task;\n  try {\n    const res = await fetch(url, { signal: AbortSignal.timeout(FETCH_TIMEOUT_MS) });\n    if (res.status === 404 || res.status === 400) return fail('fatal', 'task_not_found');\n    if (res.status >= 500 || res.status === 429 || res.status === 408) return fail('retryable', 'brain_unavailable');\n    if (!res.ok) return fail('fatal', `brain_http_${res.status}`);\n    task = await res.json();\n  } catch (error) {\n    log(`[intent] GET ${url} 失败: ${error?.message || error}`);\n    return fail('retryable', 'brain_unavailable');\n  }\n\n  const managed = task?.payload?.authority_required === true || task?.payload?.authority !== undefined\n    || task?.payload?.object_id !== undefined || task?.payload?.authority_refs !== undefined\n    || input.authority_required === true || input.authority !== undefined;\n  let authorityFacts = null;\n  if (managed) {\n    const authority = authorityFromPayload(task?.payload);\n    if (task?.payload?.authority_required !== true || input.authority_required !== true\n      || !sameAuthority(authority, input.authority)) {\n      return fail('fatal', 'authority_receipt_mismatch');\n    }\n    if (!input.trusted_repo || !input.authority_index_sha) return fail('needs_human', 'authority_index_binding_missing');\n    if (task.payload.authority_index_sha !== undefined && task.payload.authority_index_sha !== input.authority_index_sha) return fail('fatal', 'authority_index_binding_mismatch');\n    let index;\n    try { index = loadAuthorityIndex(input.trusted_repo, input.authority_index_sha); }\n    catch (error) { return fail('needs_human', error.message); }\n    const authorityErrors = validateAuthority(authority, index);\n    if (authorityErrors.length) return fail('fatal', authorityErrors[0]);\n    const fixed = task?.payload?.base_sha;\n    const initialBase = input.initial_base_sha;\n    if (typeof initialBase !== 'string' || !commitAvailable(input.worktree, initialBase)\n      || (fixed !== undefined && fixed !== initialBase)) return fail('fatal', 'authority_base_mismatch');\n    let origin;\n    try { origin = execFileSync('git', ['-C', input.worktree, 'remote', 'get-url', 'origin'], { encoding: 'utf8' }).trim(); }\n    catch { origin = null; }\n    if (!origin || resolveRepo(origin) !== task.payload.repo) return fail('fatal', 'authority_repo_mismatch');\n    authorityFacts = resolveAuthority(input.trusted_repo, authority.refs, { trustedSha: input.authority_index_sha })\n      .map((fact) => ({ ...fact, object_id: authority.object_id }));\n    const blocked = authorityFacts.find((fact) => fact.required && fact.status !== 'found');\n    if (blocked) return fail('fatal', blocked.reason, { evidence: [{ ref_id: blocked.ref_id, path: blocked.path }] });\n  }\n\n  const items = extractAcceptance(task);\n  if (items.length === 0) return fail('needs_human', 'acceptance_missing');\n\n  // 全部 active 铁律（审计 P1 #3）：拉不到不能当作没有铁律\n  let invariants;\n  try {\n    const res = await fetch(`${base}/api/brain/decisions?category=invariant&status=active&limit=${INVARIANT_LIMIT}`, { signal: AbortSignal.timeout(FETCH_TIMEOUT_MS) });\n    if (!res.ok) return fail('retryable', 'invariants_unavailable', { evidence: [{ http_status: res.status }] });\n    const body = await res.json();\n    invariants = (Array.isArray(body) ? body : body?.data ?? []).filter((r) => r?.id && (r.status ?? 'active') === 'active');\n  } catch (error) {\n    log(`[intent] 拉铁律清单失败: ${error?.message || error}`);\n    return fail('retryable', 'invariants_unavailable');\n  }\n\n  fs.mkdirSync(dir, { recursive: true });\n  const intentPath = path.join(dir, INTENT_FILE);\n  fs.writeFileSync(intentPath, renderIntent({ taskId, title: task?.title, items, description: task?.description, authorityFacts }));\n  fs.writeFileSync(path.join(dir, INVARIANTS_FILE), renderInvariants(invariants));\n\n  return {\n    status: 'completed',\n    // 验收标准的指纹：后续活动比对，发现被改即 chain_tampered\n    outputs: { intent_file: INTENT_FILE, intent_ids: items.map((_, i) => `I-${i + 1}`), intent_sha256: sha256File(intentPath) },\n    metrics: { intent_count: items.length },\n    evidence: [`${INTENT_FILE}: ${items.length} 条验收`],\n  };\n}, { stage: 'intent', entry: import.meta.url });\n",
  "packages/brain/scripts/coding-workflow/lib/authority-selection.mjs": "// 权威自动选择只认已登记对象/明确范围，冻结真实 origin/main；不从任务标题猜测。\nimport { execFileSync } from 'node:child_process';\nimport { childEnv } from './protocol.mjs';\nimport { trustedHead, loadAuthorityIndex, resolveAuthority } from './authority-refs.mjs';\n\nexport function selectAuthority(repo, { objectId, scope, repoKey, baseSha }) {\n  const revision = trustedHead(repo);\n  if (!revision) throw new Error('authority_index_binding_missing');\n  // 不把过期的 remote-tracking ref 误称“当前已合并”。不可读真实 remote 就明确失败。\n  let remote;\n  try {\n    remote = execFileSync('git', ['-C', repo, 'ls-remote', '--exit-code', 'origin', 'refs/heads/main'], {\n      encoding: 'utf8', timeout: 15000, stdio: ['ignore', 'pipe', 'ignore'],\n      env: { ...childEnv(), GIT_NO_REPLACE_OBJECTS: '1', GIT_TERMINAL_PROMPT: '0' },\n    }).trim().split(/\\s+/)[0];\n  } catch { throw new Error('authority_remote_unavailable'); }\n  if (remote !== revision) throw new Error('authority_index_stale');\n  if (baseSha !== undefined && baseSha !== revision) throw new Error('authority_selection_base_mismatch');\n  const index = loadAuthorityIndex(repo, revision);\n  if (index.selectors !== undefined && (!Array.isArray(index.selectors)\n    || index.selectors.some(s => !s || typeof s !== 'object' || typeof s.repo !== 'string' || !s.repo.trim() || typeof s.scope !== 'string' || !s.scope.trim()))) throw new Error('authority_selectors_invalid');\n  if (index.selectors === undefined || !index.selectors.length) throw new Error('authority_object_unconfigured');\n  if (objectId !== undefined && objectId !== index.object_id) throw new Error('authority_object_unsupported');\n  if (scope !== undefined) {\n    if (typeof scope !== 'string' || !scope.trim()) throw new Error('authority_scope_invalid');\n    const matches = (index.selectors ?? []).filter(s => s.repo === repoKey && s.scope === scope);\n    if (!matches.length) throw new Error('authority_scope_unmatched');\n    if (matches.length !== 1) throw new Error('authority_scope_ambiguous');\n  }\n  if (index.selectors && !index.selectors.some(s => s.repo === repoKey)) throw new Error('authority_repo_mismatch');\n  const refs = index.refs.map(ref => ({ ...ref, revision, digest: '0'.repeat(64) }));\n  const facts = resolveAuthority(repo, refs, { trustedSha: revision });\n  const failed = facts.find(f => f.reason !== 'authority_digest_mismatch' && f.status !== 'found');\n  if (failed) throw new Error(failed.reason);\n  return {\n    authority: { object_id: index.object_id, refs: refs.map((ref, i) => ({ ...ref, digest: facts[i].actual_digest })) },\n    baseSha: revision, authorityIndexSha: revision,\n  };\n}\n",
  "packages/brain/scripts/coding-workflow/new-task.mjs": "#!/usr/bin/env node\n// 建 coding workflow 任务（Commander 与 /dev 小改动的入口）：node new-task.mjs <plan.json> [--dry-run] [--repo <仓库>]\n// plan 两种形状：\n//   单条 { title, change_kind, map_scope_hint: [..], description?, acceptance: [..], priority?, gp_anchor?, base_sha? }\n//   一批 { batch?, tasks: [{ key, title, acceptance, depends_on?: [前面任务的 key], ... }] }（大改拆成有序小任务）\n// 每条建成 coding_workflow 任务（runner 自动认领跑七步链）；depends_on 的 key 换成前面已建任务的真实 id。\n// plan 顶层可写 project_id（已有 project 根）或 project: { name, description? }（先建再挂），整批都挂上；\n// 有 depends_on 时必须二选一（Brain 要求带依赖的任务挂 project 根），两者不能同时给。\n// 仓库（C6）：单条 t.repo > 计划顶层 repo > --repo > 默认仓 cecelia；别名 / owner/repo / URL 经 repos.json 归一成规范 key 写进 payload.repo，\n// 未登记的拒绝（不猜）；未启用仓库最终由 Brain 拒绝。change_kind/map_scope_hint/base_sha 可从批次顶层继承。base_sha 如提供，须为计划选定的目标仓库真实commit（通常来自origin/main），格式为40位小写hex。\n// 先整体校验再逐条创建；中途失败退出 1 并列出已建的任务。输出 [{key,id,title}]。\nimport fs from 'node:fs';\nimport { fileURLToPath } from 'node:url';\nimport { loadRepos, resolveRepo, reposFile, resolveEntry } from './runner/lib/repos.mjs';\nimport { normalizeChangeKind } from '../../src/impact-contract/change-kind.js';\nimport { validateAuthority, sameAuthority, loadAuthorityIndex, trustedHead, resolveAuthority } from './lib/authority-refs.mjs';\nimport { selectAuthority } from './lib/authority-selection.mjs';\n\nconst nonEmpty = (s) => typeof s === 'string' && s.trim() !== '';\n\n/** 计划 → { tasks（每条带 repoKey）, batch, projectId, project, errors }（errors 非空即不可建）。opts.repo：命令行 --repo。 */\nexport function validatePlan(plan, { repo = null, repos = loadRepos(reposFile()) } = {}) {\n  const raw = Array.isArray(plan?.tasks) ? plan.tasks : [plan];\n  const errors = [];\n  const keys = new Set();\n  const tasks = raw.map((t, i) => {\n    const wanted = [t?.repo, plan?.repo, repo].find((v) => nonEmpty(v)) ?? null;\n    const repoKey = resolveRepo(wanted, repos);\n    if (!repoKey) errors.push(`#${i + 1}:repo_unknown:${wanted}`);\n    const inherit = (key) => Object.hasOwn(t ?? {}, key) ? t[key] : plan?.[key];\n    let changeKind;\n    try {\n      changeKind = normalizeChangeKind(inherit('change_kind'));\n      if (!changeKind) errors.push(`#${i + 1}:change_kind_required`);\n    } catch { errors.push(`#${i + 1}:invalid_change_kind`); }\n    const baseSha = inherit('base_sha');\n    if (baseSha !== undefined && (typeof baseSha !== 'string' || !/^[a-f0-9]{40}$/.test(baseSha))) {\n      errors.push(`#${i + 1}:invalid_base_sha`);\n    }\n    const scope = inherit('map_scope_hint');\n    if (!Array.isArray(scope) || scope.length === 0) errors.push(`#${i + 1}:map_scope_required`);\n    else if (!scope.every(nonEmpty)) errors.push(`#${i + 1}:invalid_map_scope`);\n    const mapScope = Array.isArray(scope) && scope.every(nonEmpty) ? [...new Set(scope.map((v) => v.trim()))] : [];\n    const declaredObject = inherit('object_id');\n    const declaredRefs = inherit('authority_refs');\n    const nested = inherit('authority');\n    const authorityScope = inherit('authority_scope');\n    if (authorityScope !== undefined && (nested !== undefined || declaredRefs !== undefined)) errors.push(`#${i + 1}:authority_selection_conflict`);\n    const automaticAuthority = nested === undefined && declaredRefs === undefined && (declaredObject !== undefined || authorityScope !== undefined);\n    const authority = nested ?? (!automaticAuthority && (declaredObject !== undefined || declaredRefs !== undefined)\n      ? { object_id: declaredObject, refs: declaredRefs } : undefined);\n    if (nested !== undefined && (declaredObject !== undefined || declaredRefs !== undefined)\n      && !sameAuthority(nested, { object_id: declaredObject, refs: declaredRefs })) errors.push(`#${i + 1}:authority_declaration_conflict`);\n    if (authority !== undefined) errors.push(...validateAuthority(authority).map((error) => `#${i + 1}:${error}`));\n    return { ...t, repoKey, changeKind, mapScope, baseSha, authority, automaticAuthority, declaredObject, authorityScope, authorityIndexSha: undefined };\n  });\n  tasks.forEach((t, i) => {\n    const at = `#${i + 1}`;\n    if (!nonEmpty(t?.title)) errors.push(`${at}:title_missing`);\n    if (!Array.isArray(t?.acceptance) || t.acceptance.length === 0 || !t.acceptance.every(nonEmpty)) {\n      errors.push(`${at}:acceptance_missing`);\n    }\n    for (const dep of t?.depends_on ?? []) if (!keys.has(dep)) errors.push(`${at}:depends_on_unknown:${dep}`);\n    if (t?.key !== undefined) {\n      if (keys.has(t.key)) errors.push(`${at}:key_duplicate:${t.key}`);\n      keys.add(t.key);\n    }\n  });\n  const projectId = nonEmpty(plan?.project_id) ? plan.project_id : null;\n  const given = plan?.project !== undefined && plan?.project !== null;\n  if (given && !nonEmpty(plan.project?.name)) errors.push('project_name_missing');\n  if (given && plan?.project_id !== undefined) errors.push('project_conflict');\n  if (!projectId && !given && tasks.some((t) => t?.depends_on?.length)) errors.push('project_required');\n  const project = given ? { name: plan.project.name, description: plan.project.description ?? '' } : null;\n  return { tasks, batch: nonEmpty(plan?.batch) ? plan.batch : null, projectId, project, errors };\n}\n\nfunction body(t, batch, ids, projectId) {\n  const payload = {\n    coding_workflow: true,\n    repo: t.repoKey,\n    gp_anchor: nonEmpty(t.gp_anchor) ? t.gp_anchor : 'none(infra)',\n    acceptance: t.acceptance,\n  };\n  if (t.depends_on?.length) payload.depends_on = t.depends_on.map((k) => ids.get(k));\n  if (batch) payload.batch = batch;\n  if (t.key !== undefined) payload.plan_key = t.key;\n  if (t.authority !== undefined) {\n    payload.authority_required = true;\n    payload.authority = t.authority;\n    payload.object_id = t.authority.object_id;\n    payload.authority_refs = t.authority.refs;\n    if (t.authorityIndexSha) payload.authority_index_sha = t.authorityIndexSha;\n  }\n  const req = {\n    // 独立类型（派发总闸 F，任务 0a70684f）：tick 按类型排除，不再借 data + headed_manual\n    task_type: 'coding_workflow',\n    mutation_intent: 'write',\n    change_kind: t.changeKind,\n    repo_hint: t.repoKey,\n    map_scope_hint: t.mapScope,\n    title: t.title,\n    description: t.description ?? '',\n    priority: t.priority ?? 'P2',\n    trigger_source: 'manual',\n    payload,\n  };\n  if (t.baseSha !== undefined) req.base_sha = t.baseSha;\n  if (projectId) req.project_id = projectId;\n  return req;\n}\n\n/** POST JSON → { ok, reply }；网络错误折成 { ok: false, reply: { error } }。 */\nasync function postJson(url, data) {\n  try {\n    const res = await fetch(url, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(data) });\n    const reply = await res.json().catch(() => null);\n    return { ok: res.ok && Boolean(reply?.id), status: res.status, reply };\n  } catch (error) {\n    return { ok: false, status: 0, reply: { error: String(error?.message || error) } };\n  }\n}\n\nasync function receipt(url, method = 'GET', data) {\n  try {\n    const res = await fetch(url, { method, headers: { 'content-type': 'application/json' },\n      ...(data === undefined ? {} : { body: JSON.stringify(data) }) });\n    return { ok: res.ok, status: res.status, body: await res.json().catch(() => null) };\n  } catch { return { ok: false, status: 0, body: null }; }\n}\n\nfunction managedMatches(row, t) {\n  return row?.task_type === 'coding_workflow' && row?.payload?.authority_required === true\n    && sameAuthority(row.payload.authority, t.authority) && row.payload.repo === t.repoKey\n    && row.payload.object_id === t.authority.object_id\n    && sameAuthority(row.payload.authority_refs, t.authority.refs)\n    && (t.authorityIndexSha === undefined || row.payload.authority_index_sha === t.authorityIndexSha)\n    && row.payload.change_kind === t.changeKind\n    && row.payload.work_kind === 'coding_mutation'\n    && row.payload.orchestrator === 'coding-workflow-runner'\n    && Array.isArray(row.payload.map_scope)\n    && JSON.stringify([...row.payload.map_scope].sort()) === JSON.stringify([...t.mapScope].sort())\n    && (t.baseSha === undefined || row.payload.base_sha === t.baseSha);\n}\n\nasync function settleMismatch(base, id) {\n  const claim = await receipt(`${base}/tasks/${encodeURIComponent(id)}/claim`, 'POST', {\n    claimer: 'coding-workflow-new-task', executor_kind: 'coding-workflow-runner',\n  });\n  if (!claim.ok) return 'unresolved_claim';\n  const running = await receipt(`${base}/tasks/${encodeURIComponent(id)}`, 'PATCH', { status: 'in_progress' });\n  if (!running.ok) return 'unresolved_in_progress';\n  const failed = await receipt(`${base}/tasks/${encodeURIComponent(id)}`, 'PATCH', {\n    status: 'failed', result: { coding_workflow_runner: {\n      reason_code: 'authority_receipt_mismatch', detail: 'POST 与独立 GET 的受管引用或仓库路由不一致',\n      evidence: [{ task_id: id, actor: 'coding-workflow-new-task' }],\n    } },\n  });\n  if (!failed.ok) return 'unresolved_failed_patch';\n  const final = await receipt(`${base}/tasks/${encodeURIComponent(id)}`);\n  return final.ok && final.body?.status === 'failed' ? 'failed_confirmed' : 'unresolved_final_receipt';\n}\n\nconst USAGE = '用法：node new-task.mjs <plan.json> [--dry-run] [--repo <仓库>]';\n\n/** 命令行 → { file, dryRun, repo }；--repo 缺值返回 null。 */\nfunction parseArgs(argv) {\n  const out = { file: null, dryRun: false, repo: null };\n  for (let i = 0; i < argv.length; i += 1) {\n    const a = argv[i];\n    if (a === '--dry-run') out.dryRun = true;\n    else if (a.startsWith('--repo=')) out.repo = a.slice('--repo='.length);\n    else if (a === '--repo') {\n      if (!nonEmpty(argv[i + 1]) || argv[i + 1].startsWith('--')) return null;\n      out.repo = argv[i += 1];\n    } else if (!a.startsWith('--') && !out.file) out.file = a;\n  }\n  return out;\n}\n\nasync function main(argv, env) {\n  const args = parseArgs(argv);\n  if (!args?.file) {\n    console.error(USAGE);\n    return 2;\n  }\n  const { file, dryRun } = args;\n  let plan;\n  try {\n    plan = JSON.parse(fs.readFileSync(file, 'utf8'));\n  } catch (error) {\n    console.error(`读不了计划文件：${error.message}`);\n    return 2;\n  }\n  const repos = loadRepos(reposFile(env));\n  const checked = validatePlan(plan, { repo: args.repo, repos });\n  const { tasks, batch, project, errors } = checked;\n  let { projectId } = checked;\n  for (const [i, t] of tasks.entries()) {\n    if (!t.automaticAuthority || !t.repoKey) continue;\n    const clone = env.CODING_WF_TRUSTED_REPO || resolveEntry(repos.find(r => r.key === t.repoKey), env).clone;\n    try { Object.assign(t, selectAuthority(clone, { objectId: t.declaredObject, scope: t.authorityScope, repoKey: t.repoKey, baseSha: t.baseSha })); }\n    catch (error) { errors.push(`#${i + 1}:${error.message}`); }\n  }\n  if (tasks.some((t) => t.authority !== undefined)) {\n    const clone = env.CODING_WF_TRUSTED_REPO || resolveEntry(repos.find((r) => r.default), env).clone;\n    const fixed = trustedHead(clone);\n    let index;\n    try { index = fixed ? loadAuthorityIndex(clone, fixed) : null; }\n    catch (error) { errors.push(error.message); }\n    if (!index) errors.push('authority_index_binding_missing');\n    else tasks.forEach((t, i) => {\n      if (t.authority === undefined) return;\n      errors.push(...validateAuthority(t.authority, index).map((error) => `#${i + 1}:${error}`));\n      if (validateAuthority(t.authority, index).length === 0) {\n        const failed = resolveAuthority(clone, t.authority.refs, { trustedSha: fixed }).find((r) => r.required && r.status !== 'found');\n        if (failed) errors.push(`#${i + 1}:${failed.reason}`);\n      }\n    });\n  }\n  if (errors.length > 0) {\n    console.error(`计划不合格：${errors.join(' ')}`);\n    return 2;\n  }\n  if (dryRun) {\n    console.log(JSON.stringify(tasks.map((t) => ({ key: t.key ?? null, title: t.title, repo: t.repoKey, depends_on: t.depends_on ?? [] }))));\n    return 0;\n  }\n  for (const key of new Set(tasks.map((t) => t.repoKey))) {\n    if (!repos.find((r) => r.key === key)?.enabled) console.error(`注意：仓库 ${key} 在 repos.json 未启用（enabled=false），Brain 会拒绝无头建单；请先确认开闸部署`);\n  }\n  const base = `${String(env.BRAIN_URL || 'http://localhost:5221').replace(/\\/+$/, '')}/api/brain`;\n  if (project) {\n    const { ok, reply } = await postJson(`${base}/projects`, project);\n    if (!ok) {\n      console.error(`建 project 失败：${JSON.stringify(reply)}`);\n      return 1;\n    }\n    projectId = reply.id;\n  }\n  const ids = new Map();\n  const created = [];\n  for (const t of tasks) {\n    const { ok, status, reply } = await postJson(`${base}/tasks`, body(t, batch, ids, projectId));\n    if (!ok) {\n      if (t.authority !== undefined && (status === 200 || status === 201)) {\n        console.error(`authority_dedup_conflict: id=${reply?.id ?? 'unknown'}；新建身份未确认，停止后续建单`);\n        return 1;\n      }\n      console.error(`建任务「${t.title}」失败：${JSON.stringify(reply)}；已建：${JSON.stringify(created)}`);\n      return 1;\n    }\n    if (t.authority !== undefined) {\n      if (status !== 201 || reply?.deduplicated === true || !/^[a-f0-9-]{36}$/i.test(reply.id)) {\n        console.error(`authority_dedup_conflict: id=${reply.id}；复用或新建身份未确认，停止后续建单`);\n        return 1;\n      }\n      const read = await receipt(`${base}/tasks/${encodeURIComponent(reply.id)}`);\n      if (!read.ok || !managedMatches(reply, t) || !managedMatches(read.body, t)) {\n        const outcome = await settleMismatch(base, reply.id);\n        console.error(`authority_receipt_mismatch: id=${reply.id} outcome=${outcome}；停止后续建单`);\n        return 1;\n      }\n    }\n    const actual = reply.payload;\n    if (reply.task_type !== 'coding_workflow' || actual?.coding_workflow !== true\n      || actual?.work_kind !== 'coding_mutation' || actual?.orchestrator !== 'coding-workflow-runner'\n      || actual?.repo !== t.repoKey || actual?.change_kind !== t.changeKind\n      || (t.baseSha !== undefined && actual?.base_sha !== t.baseSha)\n      || !Array.isArray(actual?.map_scope)\n      || JSON.stringify([...actual.map_scope].sort()) !== JSON.stringify([...t.mapScope].sort())) {\n      console.error(`task_route_mismatch：${JSON.stringify({ id: reply.id, task_type: reply.task_type,\n        repo: actual?.repo, work_kind: actual?.work_kind, change_kind: actual?.change_kind,\n        orchestrator: actual?.orchestrator, expected_base_sha: t.baseSha, base_sha: actual?.base_sha })}；已建：${JSON.stringify(created)}；停止后续建单，先核查此任务`);\n      return 1;\n    }\n    if (t.key !== undefined) ids.set(t.key, reply.id);\n    created.push({ key: t.key ?? null, id: reply.id, title: t.title });\n  }\n  console.log(JSON.stringify(created));\n  return 0;\n}\n\nlet direct = false;\ntry {\n  direct = fs.realpathSync(process.argv[1]) === fs.realpathSync(fileURLToPath(import.meta.url));\n} catch { /* 被 import 时不执行 */ }\nif (direct) main(process.argv.slice(2), process.env).then((code) => { process.exitCode = code; });\n",
  "packages/brain/scripts/coding-workflow/runner/__tests__/authority-index-freeze.test.mjs": "import { it, expect, afterEach } from 'vitest';\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport crypto from 'node:crypto';\nimport { git } from '../../__tests__/helpers/git.mjs';\nimport { makeSandbox, startFakeBrain, codingTask, SWITCH, runnerEnv, runOnceProcess, readJsonLines } from './helpers/sandbox.mjs';\nlet sb, brain;\nafterEach(async()=>{await brain?.close();sb?.cleanup();});\nit.each(['首次', '中断重试', '绑定冲突'])('runner冻结索引：%s',async(mode)=>{\n  sb=makeSandbox();const relative='docs/registry/coding-workflow-authority.json';const index={object_id:'coding-workflow',refs:['spec','rule','sample','implementation'].map(kind=>({ref_id:kind,kind,path:'rules.md',required:true}))};\n  fs.mkdirSync(path.join(sb.seed,'docs/registry'),{recursive:true});fs.writeFileSync(path.join(sb.seed,relative),JSON.stringify(index));fs.writeFileSync(path.join(sb.seed,'rules.md'),'old');git(sb.seed,'add','.');git(sb.seed,'commit','-qm','old');const base=git(sb.seed,'rev-parse','HEAD').trim();\n  const authority={object_id:index.object_id,refs:index.refs.map(r=>({...r,revision:base,digest:crypto.createHash('sha256').update('old').digest('hex')}))};\n  index.refs[0].path='new.md';fs.writeFileSync(path.join(sb.seed,relative),JSON.stringify(index));fs.writeFileSync(path.join(sb.seed,'new.md'),'new');git(sb.seed,'add','.');git(sb.seed,'commit','-qm','new');git(sb.seed,'push','-q','origin','main');git(sb.clone,'pull','--ff-only','-q');\n  const id='aaaaaaaa-0000-4000-8000-000000000001';\n  brain=await startFakeBrain({tasks:[codingTask(id,{payload:{...SWITCH,repo:'cecelia',base_sha:base,authority_required:true,authority,authority_index_sha:base}})]});\n  if(mode !== '首次') { fs.mkdirSync(sb.logDir,{recursive:true}); fs.writeFileSync(path.join(sb.logDir,`${id}.authority-index.sha`), mode === '中断重试' ? base : git(sb.clone,'rev-parse','HEAD').trim()); }\n  const r=await runOnceProcess(runnerEnv(sb,brain.url));\n  if(mode === '绑定冲突') { expect(r.exitCode).toBe(1); expect(brain.patches.at(-1).body.result.coding_workflow_runner.reason_code).toBe('authority_index_binding_mismatch'); expect(readJsonLines(sb.execLog)).toEqual([]); return; }\n  expect(r.exitCode,r.stderr).toBe(0);const input=readJsonLines(sb.execLog)[0].envelope.input;expect(input.authority_index_sha).toBe(base);expect(input.initial_base_sha).toBe(base);expect(fs.readFileSync(path.join(sb.logDir,`${id}.authority-index.sha`),'utf8').trim()).toBe(base);\n});\n",
  "packages/brain/scripts/coding-workflow/runner/__tests__/fixtures/fake-executor.mjs": "#!/usr/bin/env node\n// 假执行器：顶替 activity-contract-run.js，按 FAKE_EXEC_MODE 产出回执，不调 claude。\n//   completed：七活动全完成，outputs.pr_url；FAKE_EXEC_REPORT=1 时像 report 活动一样 PATCH result.coding_workflow\n//   failed：verify 失败（verification_failed），report 完成，整体 partial\n//   crash：stdout 写垃圾并以 3 退出\n//   hang：永不退出（等 runner 超时）\n//   hang-tree：先拉起\"独立进程组的子进程 → 再独立进程组的孙进程\"（都忽略 SIGTERM），pid 写入 FAKE_EXEC_TREE_PIDS，然后永不退出\n//   partial-pr：publish 已开 PR，report 失败，整体 partial\n// FAKE_EXEC_LOG 指向文件时，写入一行 JSON：argv、cwd、stdin 信封、关心的 env 是否存在。\nimport fs from 'node:fs';\nimport { spawn, spawnSync } from 'node:child_process';\nimport path from 'node:path';\nimport { registerOwnedProcess } from '../helpers/owned-processes.mjs';\n\nconst argv = process.argv.slice(2);\nconst opt = (name) => {\n  const i = argv.indexOf(name);\n  return i >= 0 ? argv[i + 1] : undefined;\n};\nconst mode = process.env.FAKE_EXEC_MODE || 'completed';\n\nlet text = '';\nprocess.stdin.setEncoding('utf8');\nfor await (const chunk of process.stdin) text += chunk;\nconst envelope = JSON.parse(text);\nconst input = envelope.input;\n\nif (process.env.FAKE_EXEC_LOG) {\n  const envSeen = {};\n  for (const key of ['CLAUDECODE', 'CLAUDE_CODE_ENTRYPOINT', 'GIT_DIR', 'GIT_WORK_TREE', 'GIT_INDEX_FILE', 'CODING_WF_GH_BIN']) {\n    envSeen[key] = key in process.env;\n  }\n  fs.appendFileSync(process.env.FAKE_EXEC_LOG, `${JSON.stringify({\n    argv,\n    cwd: process.cwd(),\n    envelope,\n    env: envSeen,\n    contract_activities: envelope.contract?.activities?.map((a) => a.key),\n  })}\\n`);\n}\n\nconst KEYS = ['intent', 'spec', 'build', 'verify', 'chain_check', 'publish', 'report'];\nconst done = (key) => ({ key, status: 'completed', attempts: [{ attempt: 1, status: 'completed', outputs: {} }] });\n\nfunction finish(result, code) {\n  const receipt = opt('--receipt');\n  if (receipt) fs.writeFileSync(receipt, `${JSON.stringify(result)}\\n`);\n  process.stdout.write(`${JSON.stringify(result)}\\n`);\n  process.exitCode = code;\n}\n\n// 独立进程组、忽略 SIGTERM 的常驻进程；depth>0 时再拉起下一层。\nconst SLEEPER = `(async () => {\nprocess.on('SIGTERM', () => {});\nif (process.env.CW_TEST_PROCESS_DIR) { const m = await import(process.env.CW_TEST_PROCESS_MODULE); m.registerOwnedProcess(); }\nconst { spawn } = require('node:child_process');\nconst fs = require('node:fs');\nfs.appendFileSync(process.env.FAKE_EXEC_TREE_PIDS, process.pid + '\\\\n');\nif (Number(process.argv[1]) > 0) {\n  spawn(process.execPath, ['-e', process.env.FAKE_SLEEPER, String(Number(process.argv[1]) - 1)], { detached: true, stdio: 'ignore', env: process.env }).unref();\n}\nsetInterval(() => {}, 1000);\n})().catch(e=>{console.error(e);process.exit(1);});`;\n\nif (mode === 'hang') {\n  setInterval(() => {}, 1000);\n} else if (mode === 'hang-tree') {\n  registerOwnedProcess();\n  spawn(process.execPath, ['-e', SLEEPER, '1'], {\n    detached: true,\n    stdio: 'ignore',\n    env: { ...process.env, FAKE_SLEEPER: SLEEPER },\n  }).unref();\n  setInterval(() => {}, 1000);\n} else if (mode === 'real-intent') {\n  // 真实runner信封直接交真实intent；其他活动仍为替身，不宣称完整模型验证。\n  const child = spawn(process.execPath, [process.env.FAKE_INTENT_ENTRY], { env: process.env, stdio: ['pipe', 'pipe', 'pipe'] });\n  let stdout = '', stderr = '';\n  child.stdout.on('data', chunk => { stdout += chunk; });\n  child.stderr.on('data', chunk => { stderr += chunk; });\n  const code = await new Promise((resolve, reject) => {\n    child.once('error', reject); child.once('close', resolve); child.stdin.end(JSON.stringify(input));\n  });\n  if (stderr) process.stderr.write(stderr);\n  const result = JSON.parse(stdout);\n  let materials;\n  if (result.status === 'completed' && process.env.FAKE_MATERIAL_CHAIN === '1') materials = await (await import('./inheritance-materials.mjs')).runMaterials(input,result);\n  const terminal = materials?.result ?? result;\n  const intentPath = path.join(input.worktree, input.sprint_dir, '01-intent.md');\n  fs.appendFileSync(process.env.FAKE_INTENT_LOG, JSON.stringify({ task_id: input.task_id, input, result: terminal, materials,\n    intent: fs.existsSync(intentPath) ? fs.readFileSync(intentPath, 'utf8') : null }) + '\\n');\n  finish({ schema_version: 1, run_tag: input.run_tag, status: terminal.status,\n    outputs: { ...result.outputs, pr_url: 'https://github.com/example/repo/pull/9' }, activities: [{ key: materials ? materials.stages.at(-1).name.replace('-', '_') : 'intent', status: terminal.status, attempts: [{ attempt: 1, ...terminal }] }] }, materials?.code ?? code);\n} else if (mode === 'real-publish') {\n  // 仅替身构建环节；真实 runner 输入直接交真实 publish 子进程，捕获实际 GH 参数。\n  const dir = path.join(input.worktree, input.sprint_dir);\n  fs.mkdirSync(dir, { recursive: true });\n  for (const file of ['01-intent.md', '02-spec.md']) fs.writeFileSync(path.join(dir, file), '# test\\n');\n  const r = spawnSync(process.execPath, [process.env.FAKE_PUBLISH_ENTRY], {\n    input: JSON.stringify({ ...input, chain_files: ['01-intent.md', '02-spec.md'] }), encoding: 'utf8', env: process.env,\n  });\n  if (r.status !== 0) process.stderr.write(r.stderr + r.stdout);\n  const result = JSON.parse(r.stdout);\n  finish({ schema_version: 1, run_tag: input.run_tag, status: result.status,\n    outputs: result.outputs ?? {}, activities: KEYS.map(done) }, r.status);\n} else if (mode === 'partial-pr') {\n  finish({\n    schema_version: 1,\n    run_tag: input.run_tag,\n    status: 'partial',\n    outputs: { pr_url: 'https://github.com/example/repo/pull/9' },\n    activities: [\n      ...['intent', 'spec', 'build', 'verify', 'chain_check', 'publish'].map(done),\n      { key: 'report', status: 'failed', attempts: [{ attempt: 1, status: 'failed', failure_class: 'retryable', reason_code: 'brain_unavailable' }] },\n    ],\n  }, 2);\n} else if (mode === 'crash') {\n  process.stdout.write('not json at all\\n');\n  process.exit(3);\n} else if (mode === 'failed') {\n  finish({\n    schema_version: 1,\n    run_tag: input.run_tag,\n    status: 'partial',\n    outputs: { verification: { reason_code: 'verification_failed' } },\n    activities: [\n      ...['intent', 'spec', 'build'].map(done),\n      {\n        key: 'verify',\n        status: 'failed',\n        attempts: [{ attempt: 1, status: 'failed', failure_class: 'fatal', reason_code: 'verification_failed' }],\n      },\n      done('report'),\n    ],\n  }, 2);\n} else {\n  const prUrl = 'https://github.com/example/repo/pull/9';\n  if (process.env.FAKE_EXEC_REPORT === '1') {\n    await fetch(`${input.brain_url}/api/brain/tasks/${input.task_id}`, {\n      method: 'PATCH',\n      headers: { 'content-type': 'application/json' },\n      body: JSON.stringify({ result: { coding_workflow: { pr_url: prUrl, run_tag: input.run_tag } } }),\n    });\n  }\n  finish({\n    schema_version: 1,\n    run_tag: input.run_tag,\n    status: 'completed',\n    outputs: { pr_url: prUrl, branch: 'whatever' },\n    activities: KEYS.map(done),\n  }, 0);\n}\n",
  "packages/brain/scripts/coding-workflow/runner/__tests__/fixtures/inheritance-materials.mjs": "// 真实spec/build/chain-check/report；仅模型CLI与独立04证据为确定性替身。\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { spawn } from 'node:child_process';\nimport { fileURLToPath } from 'node:url';\nconst model=fileURLToPath(new URL('./inheritance-model.mjs',import.meta.url));\nasync function activity(entry,input) {\n  const c=spawn(process.execPath,[entry],{env:{...process.env,CODING_WF_PROVIDER:'claude',CODING_WF_CLAUDE_BIN:model,FAKE_INHERIT_INPUT:JSON.stringify(input),CODING_WF_PRECHECKS:'[]'},stdio:['pipe','pipe','pipe']});let stdout='',stderr='';\n  c.stdout.on('data',d=>{stdout+=d;});c.stderr.on('data',d=>{stderr+=d;});\n  const code=await new Promise((resolve,reject)=>{c.once('error',reject);c.once('close',resolve);c.stdin.end(JSON.stringify(input));});\n  if(stderr)process.stderr.write(stderr);return {code,result:JSON.parse(stdout)};\n}\nexport async function runMaterials(input,intent) {\n  const next={...input,...intent.outputs};const dir=path.join(input.worktree,input.sprint_dir);const stages=[];\n  for(const [name,entry] of [['spec',process.env.FAKE_SPEC_ENTRY],['build',process.env.FAKE_BUILD_ENTRY]]) {\n    const step=await activity(entry,next);stages.push({name,...step});\n    if(step.result.status!=='completed')return {...step,stages};Object.assign(next,step.result.outputs);\n  }\n  // 04不声称真实模型QA；正式runner另行独立验收。机器字段只采用真实build出参。\n  fs.writeFileSync(path.join(dir,'04-evidence.md'),`---\\ntask_id: ${input.task_id}\\nstep: verify\\nupstream: ${JSON.stringify(next.intent_ids.map(id=>`01-intent.md#${id}`))}\\n---\\n### E-1\\n离线确定性证据替身，不声称真实模型验收。\\n`);\n  next.evidence_file='04-evidence.md';\n  const chain=await activity(process.env.FAKE_CHAIN_ENTRY,next);stages.push({name:'chain-check',...chain});\n  if(chain.result.status!=='completed')return {...chain,stages};\n  Object.assign(next,chain.result.outputs,{pr_url:'https://github.com/example/repo/pull/9'});\n  const report=await activity(process.env.FAKE_REPORT_ENTRY,next);stages.push({name:'report',...report});\n  return {...report,stages,candidate:next.candidate_sha,material_sync:next.material_sync,artifacts:['01-intent.md','02-spec.md','03-build.md','04-evidence.md'].map(file=>({file,body:fs.readFileSync(path.join(dir,file),'utf8')}))};\n}\n",
  "packages/brain/scripts/coding-workflow/runner/__tests__/fixtures/inheritance-model.mjs": "#!/usr/bin/env node\n// 确定性模型CLI替身，仅产出真实spec/build活动要求的正文和业务提交。\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport crypto from 'node:crypto';\nimport { execFileSync } from 'node:child_process';\nimport { loadBaselineContext } from '../../../lib/baseline-context.mjs';\nimport { parseMaterialPlan } from '../../../lib/spec-materials.mjs';\nconst input=JSON.parse(process.env.FAKE_INHERIT_INPUT);\nconst dir=path.join(input.worktree,input.sprint_dir);\nconst prompt=process.argv[process.argv.indexOf('-p')+1]??'';\nconst hash=bytes=>crypto.createHash('sha256').update(bytes).digest('hex');\nconst fm=(step,upstream)=>`---\\ntask_id: ${input.task_id}\\nstep: ${step}\\nupstream: ${JSON.stringify(upstream)}\\n---\\n`;\nconst git=(...args)=>execFileSync('git',['-C',input.worktree,...args],{encoding:'utf8',stdio:['ignore','pipe','pipe']}).trim();\nif(/^BUILD_PATH: /m.test(prompt)) {\n  const spec=fs.readFileSync(path.join(dir,'02-spec.md'),'utf8');const plan=parseMaterialPlan(spec);\n  for(const row of plan.materials.filter(r=>r.action==='update')){fs.writeFileSync(path.join(input.worktree,row.path),`${row.ref_id} ${input.task_id}\\n`);git('add','--',row.path);}\n  git('commit','-qm','test: deterministic candidate');\n  const candidate=git('rev-parse','HEAD');const diff=git('diff','--name-status',input.initial_base_sha,candidate);\n  const record={version:1,task_id:input.task_id,run_tag:input.run_tag,base_sha:input.initial_base_sha,candidate_sha:candidate,spec_sha256:hash(spec),materials:plan.materials.map(r=>({ref_id:r.ref_id,path:r.path,action:r.action,verification:r.verification,command:'git diff --name-status',output:diff}))};\n  fs.writeFileSync(path.join(dir,'03-build.md'),fm('build',['02-spec.md#S-1'])+'### B-1\\n确定性构建替身\\n## 材料同步记录\\n```json\\n'+JSON.stringify(record)+'\\n```\\n');\n} else {\n  const baseline=loadBaselineContext(input);const change=process.env.FAKE_MATERIAL_UPDATE==='1';\n  const links={reason:'确定性集成样本',intent_ids:input.intent_ids,spec_ids:['S-1'],qa_ids:['Q-1'],approval_refs:input.intent_ids};\n  const plan={version:1,rules:baseline.rules.map(r=>({ref_id:r.ref_id,rule_id:r.rule_id,action:'keep',...links})),materials:baseline.refs.map(r=>({ref_id:r.ref_id,path:r.path,action:r.kind==='implementation'||change&&['spec','sample'].includes(r.kind)?'update':'keep',...links,verification:'git固定版本与正文摘要'}))};\n  if(process.env.FAKE_MATERIAL_VARIANT==='omit_rule')plan.rules=[];\n  if(process.env.FAKE_MATERIAL_VARIANT==='conflict')plan.rules[0].action='conflict';\n  const spec=fm('spec',input.intent_ids.map(id=>`01-intent.md#${id}`))+'### S-1\\n按批准计划同步长期资料并保留旧规则。\\n### Q-1\\n对应: '+input.intent_ids.join(', ')+'\\n前提: 固定Git基线\\n操作: 真实差异核对\\n期望: 指定材料更新、其余保留\\n## 未覆盖真实链路\\n无：仅本地Git集成范围。\\n## 旧规则与材料计划\\n```json\\n'+JSON.stringify(plan)+'\\n```\\n';\n  fs.writeFileSync(path.join(dir,'02-spec.md'),spec);\n}\nprocess.stdout.write(JSON.stringify({type:'result',result:'fixture completed',total_cost_usd:0})+'\\n');\n",
  "packages/brain/scripts/coding-workflow/runner/__tests__/helpers/sandbox.mjs": "// runner 测试沙箱：假 Brain HTTP、临时 bare origin + 专用 clone、以子进程运行 run-once.mjs。\nimport { startTestBrain } from '../../../__tests__/helpers/brain-transport.mjs';\nimport fs from 'node:fs';\nimport os from 'node:os';\nimport path from 'node:path';\nimport { spawn } from 'node:child_process';\nimport { fileURLToPath } from 'node:url';\nimport { childEnv } from '../../../lib/protocol.mjs';\nimport { git, gitPlain } from '../../../__tests__/helpers/git.mjs';\n\nconst HERE = path.dirname(fileURLToPath(import.meta.url));\nexport const RUN_ONCE = path.join(HERE, '../../run-once.mjs');\nexport const FAKE_EXECUTOR = path.join(HERE, '../fixtures/fake-executor.mjs');\nexport const FAKE_GH = path.join(HERE, '../fixtures/fake-gh.mjs');\nconst CONTRACT = path.join(HERE, '../../../contract.json');\n\nconst transports = new Map();\nconst TRANSITIONS = { queued: ['in_progress'], in_progress: ['completed', 'failed'] };\n\n/**\n * 假 Brain：tasks 为任务表（支持 status/task_type 过滤、按 created_at 降序 + limit 截断，同真 Brain）。\n * claim409 里的 id 认领返回 409；patchStatus 强制某目标状态返回指定 HTTP；\n * PATCH 按真 Brain 状态机校验（非法转移 409），终态清 claimed_by；\n * onResultPatch(task) 在只带 result 的 PATCH 后调用（模拟 Brain 重启把任务打回 queued 等）；\n * 认领对 coding-workflow-runner 强制写 kind（同真 Brain），legacyClaim=true 模拟旧端点的 COALESCE。\n */\nexport async function startFakeBrain({ tasks = [], claim409 = [], patchStatus = {}, onResultPatch, legacyClaim = false, internalToken = null, heartbeatStatus = null, getTaskStatus = null, resultPatchStatus = null, learningStatus = null, resultPatchCommittedStatus = null } = {}) {\n  const state = { tasks: structuredClone(tasks), calls: [], patches: [], learnings: [], learningRows: [], spans: [], heartbeats: [] };\n\n  const find = (id) => state.tasks.find((t) => t.id === id);\n  const send = (_res, status, body) => ({ status, headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) });\n  const transport = await startTestBrain((req) => {\n      const raw = req.body;\n      const res = null;\n      const url = new URL(req.url, 'http://x');\n      state.calls.push({ method: req.method, path: url.pathname, query: url.search, raw });\n      if (req.method === 'GET' && url.pathname === '/api/brain/tasks') {\n        const q = url.searchParams;\n        const rows = state.tasks\n          .filter((t) => (!q.get('status') || t.status === q.get('status')) && (!q.get('task_type') || t.task_type === q.get('task_type')))\n          .sort((a, b) => Date.parse(b.created_at) - Date.parse(a.created_at))\n          .slice(0, Number(q.get('limit') || 100));\n        return send(res, 200, rows);\n      }\n      // 执行记录（决策 b34e346a）：同真 Brain 的 POST /api/brain/spans（单条或数组）\n      if (req.method === 'POST' && url.pathname === '/api/brain/spans') {\n        // 同真 Brain 的 internalAuthOrLoopback：配了令牌就必须带 X-Internal-Token / Bearer\n        const provided = req.headers['x-internal-token'] || String(req.headers.authorization || '').replace(/^Bearer /, '');\n        if (internalToken && provided !== internalToken) return send(res, 401, { error: { code: 'UNAUTHORIZED' } });\n        const body = JSON.parse(raw);\n        state.spans.push(...(Array.isArray(body) ? body : [body]));\n        return send(res, 201, { inserted: Array.isArray(body) ? body.length : 1 });\n      }\n      // learnings 落库（审计 #22）：同真 Brain 的 POST /api/brain/learnings-received\n      if (req.method === 'POST' && url.pathname === '/api/brain/learnings-received') {\n        if (learningStatus) return send(res, learningStatus, { error: 'forced' });\n        const body = JSON.parse(raw);\n        state.learnings.push(body);\n        const ids = body.next_steps_suggested.map((content) => {\n          const id = `learning-${state.learningRows.length + 1}`;\n          state.learningRows.push({ id, content });\n          return id;\n        });\n        return send(res, 200, { success: true, tasks_created: 0, task_ids: [], learnings_inserted: ids.length, learning_ids: ids });\n      }\n      if (req.method === 'GET' && url.pathname === '/api/brain/learnings') {\n        const offset = Number(url.searchParams.get('offset') ?? 0);\n        const limit = Number(url.searchParams.get('limit') ?? 100);\n        return send(res, 200, { learnings: state.learningRows.slice(offset, offset + limit), total: state.learningRows.length });\n      }\n      const one = /^\\/api\\/brain\\/tasks\\/([^/]+)$/.exec(url.pathname);\n      if (req.method === 'GET' && one) {\n        if (getTaskStatus) return send(res, getTaskStatus, { error: 'forced' });\n        const task = find(one[1]);\n        return task ? send(res, 200, task) : send(res, 404, { error: 'Task not found' });\n      }\n      const claim = /^\\/api\\/brain\\/tasks\\/([^/]+)\\/claim$/.exec(url.pathname);\n      if (req.method === 'POST' && claim) {\n        const task = find(claim[1]);\n        if (!task) return send(res, 404, { error: 'Task not found' });\n        if (claim409.includes(claim[1]) || task.claimed_by) return send(res, 409, { error: 'Task already claimed' });\n        const body = JSON.parse(raw);\n        task.claimed_by = body.claimer;\n        const force = !legacyClaim && body.executor_kind === 'coding-workflow-runner';\n        task.executor_kind = force ? body.executor_kind : (task.executor_kind ?? body.executor_kind ?? 'headed-session');\n        return send(res, 200, { id: task.id, claimed_by: task.claimed_by, executor_kind: task.executor_kind });\n      }\n      // 统一领单租约心跳（任务 c5f6e683）：heartbeatStatus(n) 决定第 n 次心跳的 HTTP；未配置 = 旧 Brain 没有该端点（404）\n      const hb = /^\\/api\\/brain\\/tasks\\/([^/]+)\\/heartbeat$/.exec(url.pathname);\n      if (req.method === 'POST' && hb && heartbeatStatus) {\n        state.heartbeats.push(JSON.parse(raw));\n        const code = heartbeatStatus(state.heartbeats.length);\n        return send(res, code, code === 200 ? { ok: true } : { error: 'lease_lost' });\n      }\n      if (req.method === 'PATCH' && one) {\n\n        const body = JSON.parse(raw);\n        state.patches.push({ id: one[1], body });\n        const forced = body.status ? patchStatus[body.status] : (body.result?.merge ? resultPatchStatus : undefined);\n        if (forced) return send(res, forced, { code: 'FORCED' });\n        const task = find(one[1]);\n        if (!task) return send(res, 404, { code: 'TASK_NOT_FOUND' });\n        if (body.status && body.status !== task.status && !(TRANSITIONS[task.status] || []).includes(body.status)) {\n          return send(res, 409, { code: 'INVALID_TRANSITION', current_status: task.status });\n        }\n        if (body.status) task.status = body.status;\n        if (['completed', 'failed'].includes(body.status)) task.claimed_by = null;\n        if (body.result) task.result = { ...(task.result || {}), ...body.result };\n        if (!body.status && onResultPatch) onResultPatch(task);\n        if (body.result?.merge && resultPatchCommittedStatus) return send(res, resultPatchCommittedStatus, { code: 'ACK_LOST_AFTER_COMMIT' });\n        return send(res, 200, { id: one[1] });\n      }\n      return send(res, 404, {});\n  });\n  state.url = transport.url;\n  transports.set(state.url, transport);\n  state.close = async () => { transports.delete(state.url); await transport.close(); };\n  return state;\n}\n\n/** 开关三件套中 payload 的两项（另一项是 task_type: 'data'）。 */\nexport const SWITCH = { coding_workflow: true, headed_manual: 'true' };\n\n/** 生成一条带开关的 queued 任务。 */\nexport function codingTask(id, extra = {}) {\n  return {\n    id,\n    title: `任务 ${id.slice(0, 8)}`,\n    status: 'queued',\n    task_type: 'data',\n    claimed_by: null,\n    executor_kind: null,\n    created_at: '2026-10-08T00:00:00.000Z',\n    payload: { ...SWITCH },\n    ...extra,\n  };\n}\n\n/**\n * 临时目录：bare origin（main 上有真实 contract.json 与忽略 .dev-* 的 .gitignore）、\n * 专用 clone、worktree base、日志与锁目录。\n */\nexport function makeSandbox() {\n  const root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'cw-runner-')));\n  const origin = path.join(root, 'origin.git');\n  const seed = path.join(root, 'seed');\n  const clone = path.join(root, 'clone');\n  gitPlain('init', '--bare', '-q', '-b', 'main', origin);\n  gitPlain('init', '-q', '-b', 'main', seed);\n  git(seed, 'config', 'user.name', 'seed');\n  git(seed, 'config', 'user.email', 'seed@example.com');\n  git(seed, 'config', 'core.hooksPath', path.join(root, 'no-hooks'));\n  const wfDir = path.join(seed, 'packages/brain/scripts/coding-workflow');\n  fs.mkdirSync(wfDir, { recursive: true });\n  fs.copyFileSync(CONTRACT, path.join(wfDir, 'contract.json'));\n  fs.writeFileSync(path.join(seed, '.gitignore'), '.dev-mode*\\n.dev-lock*\\n');\n  git(seed, 'add', '.');\n  git(seed, 'commit', '-q', '-m', 'chore: seed');\n  git(seed, 'remote', 'add', 'origin', origin);\n  git(seed, 'push', '-q', 'origin', 'main');\n  gitPlain('clone', '-q', origin, clone);\n  return {\n    root,\n    origin,\n    seed,\n    clone,\n    worktreeBase: path.join(root, 'wt'),\n    logDir: path.join(root, 'logs'),\n    lockDir: path.join(root, 'lock'),\n    execLog: path.join(root, 'exec.log'),\n    ghLog: path.join(root, 'gh.log'),\n    cleanup: () => fs.rmSync(root, { recursive: true, force: true }),\n  };\n}\n\n/**\n * 测试用干净环境：在 childEnv 基础上再剥掉所有 CODING_WF_*（childEnv 为生产语义保留它们），\n * 避免外部变量泄漏进被测子进程；不修改 base。\n */\nexport function cleanTestEnv(base = process.env, opts) {\n  const env = childEnv(base, opts);\n  for (const key of Object.keys(env)) {\n    if (key.startsWith('CODING_WF_')) delete env[key];\n  }\n  return env;\n}\n\n/** runner 环境：全部外部依赖指向沙箱与假件。 */\nexport function runnerEnv(sb, brainUrl, extra = {}) {\n  // 通用fixture真身是本地x/y；self来源门用例显式提供Cecelia配置。\n  const reposPath = path.join(sb.root, 'fixture-repos.json');\n  const repos = JSON.parse(fs.readFileSync(path.join(HERE, '../../../repos.json'), 'utf8'));\n  const primary = repos.repos.find(r => r.default);\n  primary.slug = 'x/y'; primary.origin = 'https://github.com/x/y.git';\n  fs.writeFileSync(reposPath, JSON.stringify(repos));\n  return {\n    ...cleanTestEnv(process.env, { stripClaude: true }),\n    BRAIN_URL: brainUrl,\n    CODING_WF_REPOS_FILE: reposPath,\n    CODING_WF_REPO: sb.clone,\n    CODING_WF_WORKTREE_BASE: sb.worktreeBase,\n    CODING_WF_LOG_DIR: sb.logDir,\n    CODING_WF_LOCK_DIR: sb.lockDir,\n    CODING_WF_EXECUTOR: FAKE_EXECUTOR,\n    CODING_WF_GH_BIN: FAKE_GH,\n    CODING_WF_SKIP_NPM_CI: '1',\n    // CI 修复默认关：既有用例断言 gh 调用为空；ci_fix 用例显式打开\n    CODING_WF_CIFIX: '0',\n    // QA 门默认关：既有用例按「开 PR 即自动合并」断言；QA 门用例显式打开\n    CODING_WF_QA_GATE: '0',\n    // coding commander 默认关：既有用例断言升级后不再处理；commander 用例显式打开\n    CODING_WF_COMMANDER: '0',\n    // 空闲日志限频关闭（0 = 每轮都打）：既有用例断言「没有可新跑的开关任务」；限频用例显式设置\n    CODING_WF_IDLE_LOG_INTERVAL_MS: '0',\n    FAKE_EXEC_LOG: sb.execLog,\n    FAKE_GH_LOG: sb.ghLog,\n    ...extra,\n  };\n}\n\n/** 以子进程运行 run-once.mjs，返回 { exitCode, stdout, stderr }。 */\nexport function runOnceProcess(env, transport = transports.get(env.BRAIN_URL)) {\n  return new Promise((resolve, reject) => {\n    const options = transport?.spawnOptions() ?? { args: [], stdio: ['ignore', 'pipe', 'pipe'], attach() {} };\n    const args = [...options.args];\n    if (args.length) {\n      const relay = new URL('../fixtures/executor-ipc-preload.mjs', import.meta.url);\n      relay.searchParams.set('fetchPreload', args[1]);\n      relay.searchParams.set('executor', FAKE_EXECUTOR);\n      for (const entry of [env.FAKE_INTENT_ENTRY, env.FAKE_SPEC_ENTRY, env.FAKE_BUILD_ENTRY, env.FAKE_CHAIN_ENTRY, env.FAKE_REPORT_ENTRY].filter(Boolean)) relay.searchParams.append('activity', entry);\n      args.push('--import', relay.href);\n    }\n    const child = spawn(process.execPath, [...args, RUN_ONCE], { env, stdio: options.stdio });\n    options.attach(child);\n    child.stdin?.end();\n    let stdout = '';\n    let stderr = '';\n    child.stdout.setEncoding('utf8');\n    child.stderr.setEncoding('utf8');\n    child.stdout.on('data', (d) => { stdout += d; });\n    child.stderr.on('data', (d) => { stderr += d; });\n    child.on('error', reject);\n    child.on('close', (exitCode) => resolve({ exitCode, stdout, stderr }));\n  });\n}\n\n/** 读 JSON 行日志文件；不存在返回 []。 */\nexport function readJsonLines(file) {\n  if (!fs.existsSync(file)) return [];\n  return fs.readFileSync(file, 'utf8').trim().split('\\n').filter(Boolean).map((l) => JSON.parse(l));\n}\n",
  "packages/brain/scripts/coding-workflow/runner/run-once.mjs": "#!/usr/bin/env node\n// coding workflow runner：每次调用至多新跑一条开关任务（task_type=coding_workflow；迁移窗口内兼容旧三件套\n// task_type=data + payload.headed_manual=\"true\" + payload.coding_workflow===true）：保留期清理 → 对账（本机丢失的 in_progress、带本机痕迹的 queued）\n// → 自己开的 cw PR 有 CI 红则本轮只修它（lib/cifix.mjs）→ CI 绿的过AI QA 门（lib/qa-gate.mjs，PASS 才开自动合并）\n// → 认领 → 建 worktree → 跑 coding 链 → 回写 Brain。\n// 退出码：0 = 无新任务 / 上一轮仍在跑 / 新任务完成；1 = 新任务失败或 runner 自身出错。\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { fileURLToPath } from 'node:url';\nimport { loadConfig } from './lib/config.mjs';\nimport { acquireLock } from './lib/lock.mjs';\nimport { brainClient, EXECUTOR_KIND } from './lib/brain.mjs';\nimport { isSwitched, hasRunResult, pickCandidates, taskNames, runTimeoutMs } from './lib/plan.mjs';\nimport { prepareWorktree } from './lib/worktree.mjs';\nimport { cleanupRetention } from './lib/retention.mjs';\nimport { runExecutor } from './lib/executor.mjs';\nimport { chainSpans, postSpans } from './lib/spans.mjs';\nimport { readReceipt, summarizeReceipt } from './lib/receipt.mjs';\nimport { failTask, finishSuccess, localSummary, lostSummary, settle, settleQueued } from './lib/terminal.mjs';\nimport { runCiFix } from './lib/cifix.mjs';\nimport { runQaGate } from './lib/qa-gate.mjs';\nimport { runMergeGate, settleHumanMerges } from './lib/merge-gate.mjs';\nimport { runCommander } from './lib/commander.mjs';\nimport { listOwnPrs } from './lib/cifix-scan.mjs';\nimport { idleLogDue } from './lib/session-log.mjs';\nimport { restoreStates, mirrorStates } from './lib/state-store.mjs';\nimport { prepareStateSync } from './lib/pr-sync.mjs';\nimport { settleClosedPrs } from './lib/pr-closure.mjs';\nimport { readyCandidates } from './lib/deps.mjs';\nimport { repoViews, taskView } from './lib/repos.mjs';\nimport { startLeaseHeartbeat } from './lib/lease.mjs';\nimport { commitAvailable, sameAuthority, validateAuthority, loadAuthorityIndex, trustedHead, authorityFromPayload } from '../lib/authority-refs.mjs';\nimport { git } from './lib/proc.mjs';\n\nconst HERE = path.dirname(fileURLToPath(import.meta.url));\nconst WORKFLOW_REL = 'packages/brain/scripts/coding-workflow';\nconst EXECUTOR_REL = 'packages/brain/scripts/activity-contract-run.js';\nconst LOCK_EXTRA_MS = 60 * 60 * 1000;\n\nconst log = (...args) => console.error(`[${new Date().toISOString()}] [coding-workflow-runner]`, ...args);\n\nfunction readContract(file) {\n  try {\n    return JSON.parse(fs.readFileSync(file, 'utf8'));\n  } catch {\n    throw new Error('contract_unreadable');\n  }\n}\n\n/** 本机 runner 认领的 in_progress 任务：本进程已持锁 = 原执行者已不在，按本机痕迹收尾（无终态回执即 runner_lost）。 */\nasync function settleLost(ctx) {\n  const rows = await ctx.brain.listTasks('in_progress');\n  for (const task of rows.filter((t) => isSwitched(t) && t.claimed_by === ctx.cfg.claimer)) {\n    const local = localSummary(ctx.cfg, task.id);\n    const summary = local && local.reason_code !== 'runner_lost'\n      ? local\n      : lostSummary('runner 已不在（本机锁空闲）且没有终态回执');\n    log(`对账本机丢失的 in_progress 任务 ${task.id}：${summary.reason_code ?? 'completed'}`);\n    await settle(ctx, task, summary);\n  }\n}\n\n/** queued 开关任务：挂着本机 claim 或本机有痕迹的先对账收尾；其余里挑最早的未跑过的新任务。 */\nasync function pickNew(ctx, queued) {\n  const { cfg } = ctx;\n  const traced = new Set();\n  for (const task of queued.filter(isSwitched)) {\n    const local = localSummary(cfg, task.id);\n    if (local) traced.add(task.id);\n    if (!local && task.claimed_by !== cfg.claimer) continue;\n    log(`对账 queued 任务 ${task.id}（本机${local ? '有运行痕迹' : ' claim 残留'}），不重跑`);\n    await settleQueued(ctx, task, local ?? lostSummary('任务挂着本机 claim 但本机没有运行痕迹'));\n  }\n  return pickCandidates(queued, { enabled: cfg.repos.map((r) => r.key), log }).filter((task) => {\n    if (traced.has(task.id)) return false;\n    if (hasRunResult(task)) {\n      log(`任务 ${task.id} 已有运行结果（result.coding_workflow/runner/coding_workflow_runner），不认领`);\n      return false;\n    }\n    return true;\n  });\n}\n\nasync function claimFirst(ctx, candidates) {\n  if (candidates.length === 0) {\n    // 空闲 tick 每 5 分钟一次：限频（默认每小时最多一行），免得刷满主日志\n    if (idleLogDue(ctx.cfg)) log('没有可新跑的开关任务');\n    return null;\n  }\n  for (const task of candidates) {\n    const r = await ctx.brain.claim(task.id, ctx.cfg.claimer, ctx.cfg.leaseSeconds);\n    if (r.ok) return { ...task, claimed_kind: r.body?.executor_kind ?? null };\n    log(`认领 ${task.id} 失败（HTTP ${r.status}），换下一条`);\n  }\n  return null;\n}\n\n/** 建 worktree 并跑执行器；返回回执摘要。任一步失败抛 Error(reason_code)。ctx.cfg 是任务所在仓库的视图。 */\nasync function execute(ctx, task, job, signal) {\n  const { cfg } = ctx;\n  const names = taskNames(task.id);\n  fs.mkdirSync(cfg.logDir, { recursive: true });\n  const freezeFile = path.join(cfg.logDir, `${task.id}.initial-base.sha`);\n  const judgeRepo = cfg.trustedRepo ?? cfg.repo;\n  let authorityIndexSha = null;\n  if (task.payload?.authority_required === true) {\n    const binding = path.join(cfg.logDir, `${task.id}.authority-index.sha`);\n    if (fs.existsSync(binding)) {\n      authorityIndexSha = fs.readFileSync(binding, 'utf8').trim();\n    } else {\n      if (fs.existsSync(freezeFile) || fs.existsSync(job.receiptPath)) throw new Error('authority_index_binding_missing');\n      authorityIndexSha = task.payload.authority_index_sha ?? trustedHead(judgeRepo);\n      if (!authorityIndexSha) throw new Error('authority_index_binding_missing');\n      // 首次绑定必须由独立更新的可信 clone 提供；未入 origin/main 的索引不能建成受管任务。\n      loadAuthorityIndex(judgeRepo, authorityIndexSha);\n      fs.writeFileSync(binding, `${authorityIndexSha}\\n`, { flag: 'wx' });\n    }\n    if (task.payload.authority_index_sha !== undefined && task.payload.authority_index_sha !== authorityIndexSha) throw new Error('authority_index_binding_mismatch');\n    const index = loadAuthorityIndex(judgeRepo, authorityIndexSha);\n    const errors = validateAuthority(authorityFromPayload(task.payload), index);\n    if (errors.length) throw new Error(errors[0]);\n  }\n  if (task.payload?.authority_required === true && task.payload?.base_sha === undefined && !fs.existsSync(freezeFile)) {\n    const fetched = await git(cfg.repo, ['fetch', 'origin', 'main']);\n    if (fetched.code !== 0) throw new Error('git_fetch_failed');\n    const base = await git(cfg.repo, ['rev-parse', '--verify', 'origin/main^{commit}']);\n    if (base.code !== 0 || !commitAvailable(cfg.repo, base.stdout.trim())) throw new Error('initial_base_unavailable');\n    fs.writeFileSync(freezeFile, `${base.stdout.trim()}\\n`, { flag: 'wx' });\n  }\n  if (task.payload?.base_sha === undefined && fs.existsSync(freezeFile)) {\n    const frozen = fs.readFileSync(freezeFile, 'utf8').trim();\n    if (!commitAvailable(cfg.repo, frozen)) throw new Error('initial_base_unavailable');\n    task = { ...task, payload: { ...task.payload, base_sha: frozen } };\n  }\n  // worktree 来自任务所在仓库的 clone（cfg.repo）、建在它的 worktree 根\n  const worktree = await prepareWorktree(cfg, task, names, job, signal);\n  const head = await git(worktree, ['rev-parse', 'HEAD']);\n  if (head.code !== 0) throw new Error('initial_base_unavailable');\n  const initialBase = task.payload?.base_sha ?? head.stdout.trim();\n  if (head.stdout.trim() !== initialBase) throw new Error('initial_base_mismatch');\n  if (!commitAvailable(worktree, initialBase)) throw new Error('initial_base_unavailable');\n  if (fs.existsSync(freezeFile) && fs.readFileSync(freezeFile, 'utf8').trim() !== initialBase) throw new Error('initial_base_mismatch');\n  if (!fs.existsSync(freezeFile)) fs.writeFileSync(freezeFile, `${initialBase}\\n`, { flag: 'wx' });\n  // 判卷代码（契约、执行器、各活动）一律来自默认仓 runner 专用 clone（每轮自更新到 main），不来自任务 worktree / 任务仓库：\n  // build 改过的 verify/chain_check 不能拿来判它自己（审计 P0 #1，对应旧 harness「judge 不在被评 worktree 跑」）\n  const trusted = path.join(judgeRepo, WORKFLOW_REL);\n  const contract = readContract(path.join(trusted, 'contract.json'));\n  const envelope = {\n    contract,\n    input: {\n      run_tag: names.runTag, task_id: task.id, worktree, sprint_dir: names.sprintDir, brain_url: cfg.brainUrl,\n      ...(task.payload?.authority_required === true ? { authority: authorityFromPayload(task.payload), authority_required: true } : {}),\n      ...(authorityIndexSha ? { authority_index_sha: authorityIndexSha, trusted_repo: judgeRepo } : {}),\n      initial_base_sha: initialBase,\n      // 只透传任务登记值；不采用 .dev-mode 为兼容旧任务生成的豁免缺省。\n      ...(task.payload?.gp_anchor !== undefined ? { gp_anchor: task.payload.gp_anchor } : {}),\n      // 活动层按仓库参数化（C6）：版本碎片、CI 预检清单、本仓规矩提示词、QA 模式随任务所在仓库的 repos.json 条目走\n      ...(cfg.repoProfile ? { repo_profile: cfg.repoProfile } : {}),\n    },\n  };\n  log(`开跑 ${task.id}：worktree=${worktree} branch=${names.branch}`);\n  const startedAt = Date.now();\n  const r = await runExecutor({\n    executor: cfg.executor ?? path.join(judgeRepo, EXECUTOR_REL),\n    cwdDir: trusted,\n    worktree,\n    envelope,\n    receiptPath: job.receiptPath,\n    logPath: path.join(cfg.logDir, `${task.id}.log`),\n    timeoutMs: cfg.runTimeoutMs ?? runTimeoutMs(contract),\n    killGraceMs: cfg.killGraceMs,\n    signal,\n  });\n  if (r.aborted) throw new Error('runner_terminated');\n  if (r.timedOut) throw new Error('executor_timeout');\n  const receipt = readReceipt(r.stdout, job.receiptPath);\n  if (!receipt) throw new Error('executor_crashed');\n  // 执行记录（决策 b34e346a）：每个活动的每次尝试一条 span\n  await postSpans(ctx, chainSpans(receipt, { taskId: task.id, startedAt }));\n  return summarizeReceipt(receipt);\n}\n\n/**\n * 门禁按仓库遍历（repos.json 顺序，C5）：每个已启用仓库用自己的视图（clone / worktree 根 / 状态命名空间 / GH_REPO）\n * 跑一遍各道门；任一仓库做了事返回 true（本轮到此，保持「一轮只做一件事」）。clone 不存在（runner.sh 没 clone 成）的仓库跳过。\n */\nasync function runGates(ctx, signal) {\n  const { cfg } = ctx;\n  if (!cfg.qaGate && !cfg.ciFix && !cfg.commander) return false;\n  for (const view of repoViews(cfg)) {\n    if (!fs.existsSync(view.repo)) {\n      log(`仓库 ${view.repoKey} 的 clone ${view.repo} 不存在，本轮跳过它的门禁`);\n      continue;\n    }\n    if (await runRepoGates({ ...ctx, cfg: view }, signal)) return true;\n  }\n  return false;\n}\n\n/**\n * 一个仓库的门：合并门 → commander → CI 修复 → QA 门；有一个做了事返回 true。\n * 状态外部真相（审计 #34）：跑之前本机缺状态文件的 PR 从 Brain 恢复，跑完把有变化的关键字段写回 Brain。\n */\nasync function runRepoGates(ctx, signal) {\n  const { cfg } = ctx;\n  const prs = await listOwnPrs(cfg).catch(() => null);\n  await prepareStateSync(ctx, prs);\n  await restoreStates(ctx, [...ctx.syncPrs.values()]);\n  try {\n    // 外部关闭（未合并）的 PR 收尾、重开恢复、已结束的停预览：不算本轮动作，不挡后面的门\n    await settleClosedPrs(ctx, prs);\n    // 不自动合并的仓库：等人合并的 PR 被人合并了 → 收账（不算本轮动作）\n    if (cfg.qaGate) await settleHumanMerges(ctx);\n    // 已批准的 PR：只合并被批准的 head（批准后又改了代码则撤销批准，本轮到此）\n    if (cfg.qaGate && await runMergeGate(ctx)) return true;\n    // 升级了的 PR：coding commander 裁决并解除（或上交主理人），本轮到此（决策 c167d6e3）\n    if (cfg.commander && await runCommander(ctx, signal)) return true;\n    // 先收尾再开新：自己开的 PR CI 红了，本轮只修它\n    if (cfg.ciFix && await runCiFix(ctx, signal)) return true;\n    // CI 绿了：AI QA 门（PASS 才开自动合并，FAIL 进修复环）\n    return Boolean(cfg.qaGate && await runQaGate(ctx, signal));\n  } finally {\n    await mirrorStates(ctx, prs);\n  }\n}\n\nexport async function runOnce(cfg, signal) {\n  await cleanupRetention(cfg).catch((error) => log(`保留期清理失败：${error.message}`));\n  const ctx = { cfg, brain: brainClient(cfg.brainUrl, { listLimit: cfg.listLimit, log }), log };\n  let task;\n  try {\n    await settleLost(ctx);\n    if (await runGates(ctx, signal)) return 0;\n    const fresh = await pickNew(ctx, await ctx.brain.listTasks('queued'));\n    task = await claimFirst(ctx, await readyCandidates(ctx, fresh));\n  } catch (error) {\n    log(`查询/对账/认领失败：${error.message}`);\n    return 1;\n  }\n  if (!task) return 0;\n\n  const started = await ctx.brain.patch(task.id, { status: 'in_progress' });\n  if (!started.ok) {\n    log(`已认领 ${task.id} 但置 in_progress 失败（HTTP ${started.status}），不开跑`);\n    return 1;\n  }\n\n  const startedAt = Date.now();\n  const job = { worktree: null, branch: null, receiptPath: path.join(cfg.logDir, `${task.id}.json`) };\n  // 任务所在仓库的视图：worktree 建在该仓库 clone，收尾删 worktree 也用它（日志目录 / 回执路径不变）\n  const tctx = { ...ctx, cfg: taskView(cfg, task) };\n  // Brain 没把 kind 记成 coding-workflow-runner（旧端点保留历史残留）：重启会被当本机执行体打回重跑，不跑链\n  if (task.claimed_kind !== EXECUTOR_KIND) {\n    const detail = `认领响应 executor_kind=${task.claimed_kind ?? '空'}，不是 ${EXECUTOR_KIND}`;\n    log(`任务 ${task.id} ${detail}，不跑链`);\n    return failTask(tctx, task, job, { status: 'failed', failed_activity: null, reason_code: 'executor_kind_mismatch', pr_url: null, detail });\n  }\n  const read = await ctx.brain.getTask(task.id);\n  const current = read.body;\n  if (!read.ok || current?.id !== task.id) {\n    return failTask(tctx, task, job, { status: 'failed', failed_activity: 'intent',\n      reason_code: 'task_receipt_unavailable', pr_url: null, detail: `无法核实任务 ${task.id} 的领单回执` });\n  }\n  const managed = task.payload?.authority_required === true || task.payload?.authority !== undefined\n    || task.payload?.object_id !== undefined || task.payload?.authority_refs !== undefined\n    || current.payload?.authority_required === true || current.payload?.authority !== undefined\n    || current.payload?.object_id !== undefined || current.payload?.authority_refs !== undefined;\n  if (managed) {\n    if (current?.payload?.authority_required !== true\n      || validateAuthority(authorityFromPayload(current?.payload)).length > 0\n      || !sameAuthority(authorityFromPayload(current.payload), authorityFromPayload(task.payload))\n      || current.payload.authority_index_sha !== task.payload.authority_index_sha\n      || task.payload?.authority_required !== true || current.payload.repo !== task.repoKey) {\n      return failTask(tctx, task, job, { status: 'failed', failed_activity: 'intent',\n        reason_code: 'authority_receipt_mismatch', pr_url: null,\n        detail: `受管声明或仓库路由回执不一致：task_id=${task.id}` });\n    }\n  }\n  task = { ...current, repoKey: task.repoKey, claimed_kind: task.claimed_kind };\n  let summary;\n  // 统一领单租约：执行期间心跳续约；409 lease_lost → 中止执行器，Brain 已按租约语义处置，不再回写终态\n  const leaseAbort = new AbortController();\n  const onOuterAbort = () => leaseAbort.abort();\n  signal?.addEventListener('abort', onOuterAbort, { once: true });\n  const beat = startLeaseHeartbeat({\n    brain: ctx.brain, taskId: task.id, claimer: cfg.claimer, leaseSeconds: cfg.leaseSeconds, intervalMs: cfg.heartbeatMs, log,\n    onLost: () => leaseAbort.abort(),\n  });\n  try {\n    summary = await execute(tctx, task, job, leaseAbort.signal);\n  } catch (error) {\n    summary = { status: 'failed', failed_activity: null, reason_code: error?.message || 'runner_error', pr_url: null };\n  } finally {\n    beat.stop();\n    signal?.removeEventListener('abort', onOuterAbort);\n  }\n  if (beat.lost()) {\n    log(`任务 ${task.id} 租约已被 Brain 回收（lease_lost）：执行器已中止，不回写终态；现场 ${job.worktree ?? '无'}`);\n    return 1;\n  }\n  try {\n    if (summary.status === 'completed' && !summary.reason_code) {\n      return await finishSuccess(tctx, task, job, summary, { duration_s: Math.round((Date.now() - startedAt) / 1000) });\n    }\n    return await failTask(tctx, task, job, summary);\n  } catch (error) {\n    // 收尾本身出错也要尽力回写，不留 in_progress 孤儿\n    log(`收尾异常：${error?.stack || error}`);\n    return failTask(tctx, task, job, { ...summary, reason_code: 'runner_finalize_error' });\n  }\n}\n\n/** 最长持锁 = 总超时 + 1 小时；超过即视为陈旧（防 pid 复用让死锁永不释放）。 */\nfunction maxHoldMs(cfg) {\n  let total = cfg.runTimeoutMs;\n  if (!total) {\n    try {\n      total = runTimeoutMs(readContract(path.join(HERE, '../contract.json')));\n    } catch {\n      total = runTimeoutMs({});\n    }\n  }\n  return total + LOCK_EXTRA_MS;\n}\n\nexport async function main(env = process.env) {\n  const cfg = loadConfig(env);\n  let lock;\n  try {\n    lock = acquireLock(cfg.lockDir, { maxHoldMs: maxHoldMs(cfg) });\n  } catch (error) {\n    log(`取锁失败：${error.message}`);\n    return 1;\n  }\n  if (!lock) {\n    log('上一轮仍在运行，本轮退出');\n    return 0;\n  }\n  const abort = new AbortController();\n  const stop = () => abort.abort();\n  process.on('SIGTERM', stop);\n  process.on('SIGINT', stop);\n  try {\n    return await runOnce(cfg, abort.signal);\n  } finally {\n    process.off('SIGTERM', stop);\n    process.off('SIGINT', stop);\n    lock.release();\n  }\n}\n\nlet directEntry = false;\ntry {\n  directEntry = Boolean(process.argv[1])\n    && fs.realpathSync(process.argv[1]) === fs.realpathSync(fileURLToPath(import.meta.url));\n} catch { /* 被 import 时不启动 */ }\nif (directEntry) {\n  main().then((code) => { process.exitCode = code; }, (error) => {\n    log(`未捕获异常：${error?.stack || error}`);\n    process.exitCode = 1;\n  });\n}\n"
};

